from datetime import datetime, timedelta

class ContactMonitor:
    def __init__(self, user_id, max_contacts_per_day=5, retention_days=30):
        self.user_id = user_id
        self.max_contacts_per_day = max_contacts_per_day
        self.retention_days = retention_days
        self.log = []

    def record_contact(self, channel, purpose, consent=True):
        if not consent:
            return {"status": "blocked", "reason": "No consent"}
        now = datetime.now()
        today = [e for e in self.log if e["time"].date() == now.date()]
        if len(today) >= self.max_contacts_per_day:
            return {"status": "limited", "reason": "Daily contact limit reached"}
        self.log.append({"time": now, "channel": channel, "purpose": purpose})
        self._prune()
        return {"status": "recorded"}

    def _prune(self):
        cutoff = datetime.now() - timedelta(days=self.retention_days)
        self.log = [e for e in self.log if e["time"] >= cutoff]

    def summary(self):
        return {
            "user_id": self.user_id,
            "contacts_logged": len(self.log),
            "recent": [e["purpose"] for e in self.log[-5:]]
        }
